331	pub fn instance_descriptor(force_backend: Option<&str>) -> wgpu::InstanceDescriptor {
332	    let backends = if let Some(force_backend) = force_backend {
333	        if let Some(backend) = parse_graphics_backend(force_backend) {
334	            if let Err(err) = validate_graphics_backend_applicability(backend) {
335	                re_log::error!("Failed to force rendering backend parsed from {force_backend:?}: {err}\nUsing default backend instead.");
336	                supported_backends()
337	            } else {
338	                re_log::info!("Forcing graphics backend to {backend:?}.");
339	                backend.into()
340	            }
341	        } else {
342	            re_log::error!("Failed to parse rendering backend string {force_backend:?}. Using default backend instead.");
343	            supported_backends()
344	        }
345	    } else {
346	        supported_backends()
347	    };
348	
349	    wgpu::InstanceDescriptor {
350	        backends,
351	
352	        flags: wgpu::InstanceFlags::default()
353	            // Allow adapters that aren't compliant with the backend they're implementing.
354	            // A concrete example of this is the latest Vulkan drivers on WSL which (as of writing)
355	            // advertise themselves as not being Vulkan compliant but work fine for the most part.
356	            //
357	            // In the future we might consider enabling this _only_ for WSL as this might otherwise
358	            // cause us to run with arbitrary development versions of drivers.
359	            // (then again, if a user has such a driver they likely *want* us to run with it anyways!)
360	            .union(wgpu::InstanceFlags::ALLOW_UNDERLYING_NONCOMPLIANT_ADAPTER)
361	            // Allow manipulation via environment variables.
362	            .with_env(),
363	
364	        // FXC isn't great (slow & outdated), but DXC is painful to ship as it has to be provided separately.
365	        // (Note though that we generally prefer running with Vulkan)
366	        dx12_shader_compiler: wgpu::Dx12Compiler::Fxc,
367	
368	        gles_minor_version: wgpu::Gles3MinorVersion::Automatic,
369	    }
370	}
