372	/// Returns an instance descriptor that is suitable for testing.
373	pub fn testing_instance_descriptor() -> wgpu::InstanceDescriptor {
374	    // We don't test on GL & DX12 right now (and don't want to do so by mistake!).
375	    // Several reasons for this:
376	    // * our CI is setup to draw with native Mac & lavapipe
377	    // * we generally prefer Vulkan over DX12 on Windows since it reduces the
378	    //   number of backends and wgpu's DX12 backend isn't as far along as of writing.
379	    // * we don't want to use the GL backend here since we regard it as a fallback only
380	    //   (TODO(andreas): Ideally we'd test that as well to check it is well-behaved,
381	    //   but for now we only want to have a look at the happy path)
382	    let backends = wgpu::Backends::VULKAN | wgpu::Backends::METAL;
383	
384	    let flags = (
385	        wgpu::InstanceFlags::ALLOW_UNDERLYING_NONCOMPLIANT_ADAPTER | wgpu::InstanceFlags::VALIDATION
386	        // TODO(andreas): GPU based validation layer sounds like a great idea,
387	        // but as of writing this makes tests crash on my Windows machine!
388	        // It looks like the crash is in the Vulkan/Nvidia driver, but further investigation is needed.
389	        // | wgpu::InstanceFlags::GPU_BASED_VALIDATION
390	    )
391	        .with_env(); // Allow overwriting flags via env vars.
392	
393	    wgpu::InstanceDescriptor {
394	        backends,
395	        flags,
396	        ..instance_descriptor(None)
397	    }
398	}
