438	/// Backends that are officially supported by `re_renderer`.
439	///
440	/// Other backend might work as well, but lack of support isn't regarded as a bug.
441	pub fn supported_backends() -> wgpu::Backends {
442	    if cfg!(native) {
443	        // Native: Everything but DX12
444	        // * Wgpu's DX12 impl isn't in a great shape yet and there's now reason to add more variation
445	        //   when we can just use Vulkan
446	        //   So far, the main reason against it would be that some Windows VMs only provide DX12 drivers,
447	        //   observed with Parallels on Apple Silicon. In the future we might want to reconsider
448	        //   based on surface/presentation support which may be better with DX12.
449	        // * We'd like to exclude GL, but on Linux this can be a very useful fallback for users with
450	        //   with old hardware or bad/missing drivers. Wgpu automatically prefers Vulkan over GL when possible.
451	        //
452	        // For changing the backend we use standard wgpu env var, i.e. WGPU_BACKEND.
453	        wgpu::util::backend_bits_from_env()
454	            .unwrap_or(wgpu::Backends::VULKAN | wgpu::Backends::METAL | wgpu::Backends::GL)
455	    } else {
456	        wgpu::Backends::GL | wgpu::Backends::BROWSER_WEBGPU
457	    }
458	}
